function receipt = f90_xtherm05_measurement(modelPath,outDir)
%F90_XTHERM05_SCORE_MODEL Dedicated distributed cooling-plate scorer.
% Required non-nominal capability is aggregated by worst scenario, while
% paired flow scenarios verify that public flow acts in the physical path.
arguments
    modelPath (1,1) string
    outDir (1,1) string
end

repoRoot = string(getenv("SIMUVERITY_TASK_VENDOR_ROOT"));
sourceRoot = fullfile(string(getenv("SIMUVERITY_TASK_ROOT")), ...
    "reference", "files", "Battery-Cooling-Plate-Simscape");
addpath(fullfile(repoRoot,"scripts","xp9"));
addpath(fullfile(repoRoot,"scripts","formal90","tasks","f90_xtherm05"));
def = f90_xtherm05_definition;
if ~isfolder(outDir),mkdir(outDir);end

receipt = struct( ...
    "schema","simuverity.f90-xtherm05-score.v1", ...
    "policy_id","simuverity-101-v1:f90-xtherm-05:scoring", ...
    "formula","G*100*A^0.20*Q^0.17*M^0.25*R^0.23*D^0.15", ...
    "task_id",def.id, ...
    "formal_id",def.formal_id, ...
    "model_path",modelPath, ...
    "model_file_presence","", ...
    "matlab_release",string(version("-release")), ...
    "started_at",timestamp(), ...
    "score_inputs_valid",false, ...
    "diagnostics_valid",false, ...
    "G",false, ...
    "gate_reasons",strings(0,1), ...
    "A",0,"Q",0,"M",0,"R",0,"D",0, ...
    "score",0, ...
    "groups",struct("G",0,"A",0,"Q",0,"M",0,"R",0,"D",0), ...
    "raw_metrics",struct, ...
    "utility_metrics",struct, ...
    "scenario_rows",struct([]), ...
    "static_audit",struct, ...
    "failure_reasons",strings(0,1), ...
    "diagnostic_scope",struct( ...
        "D_scope","CC-active low-limit triplet with 1:1 total-pack ampere response", ...
        "D_score_role","counted", ...
        "scenarios","evaluator-owned fixed points inside public ranges"), ...
    "error","");

old = pwd;
cleanupDir = onCleanup(@() cd(old)); %#ok<NASGU>
project = [];
try
    assert(isfile(modelPath),"F90_XTHERM05_MODEL_MISSING");
    receipt.model_file_presence = xp9_file_presence_file(modelPath);
    cd(sourceRoot);
    project = openProject(fullfile(sourceRoot,"BatteryCoolingPlateSimscape.prj"));
    cleanupProject = onCleanup(@() close_project(project)); %#ok<NASGU>
    load_system(modelPath);
    [~,model] = fileparts(modelPath);
    cleanupModel = onCleanup(@() close_if_loaded(model)); %#ok<NASGU>
    set_param(model,"SimulationCommand","update");
    static = static_audit(model,def);
    receipt.static_audit = static;
    if ~static.core_path_qualified
        receipt.gate_reasons = ...
            "core electro-thermal-fluid topology was not qualified";
        error("F90_XTHERM05_STATIC_CORE_INVALID", ...
            "Core physical topology/output-origin audit failed");
    end

    names = ["nominal",string({def.scenarios.id})];
    values = cell(numel(names),1);
    values{1} = nominal_values(def);
    for index = 1:numel(def.scenarios)
        values{index+1} = def.scenarios(index).values;
    end
    rows = repmat(empty_row,numel(names),1);
    runFailures = strings(0,1);
    for index = 1:numel(names)
        try
            rows(index) = run_scenario(model,names(index),values{index},def);
        catch scenarioError
            rows(index).id = names(index);
            rows(index).error = string(getReport(scenarioError, ...
                "extended","hyperlinks","off"));
            runFailures(end+1,1) = names(index) + ": " + ...
                string(scenarioError.identifier); %#ok<AGROW>
        end
    end
    receipt.scenario_rows = rows;
    platformValid = all([rows.valid]);
    receipt.score_inputs_valid = platformValid;
    if ~platformValid
        receipt.gate_reasons = ["required scenario or output contract failed";runFailures];
        error("F90_XTHERM05_SCENARIO_INVALID", ...
            "One or more required scenario runs were invalid");
    end

    nominal = rows(1);
    Ametrics = struct( ...
        "initial_temperature_error_K",nominal.initial_temperature_error_K, ...
        "pre_step_current_limit_utilization",nominal.pre_current_utilization, ...
        "post_step_current_limit_utilization",nominal.post_current_utilization, ...
        "cell_equivalent_voltage_V",nominal.voltage_tail_V);
    Autilities = struct( ...
        "initial_temperature",q_low(nominal.initial_temperature_error_K,.15,2.0), ...
        "pre_step_charging",q_band(nominal.pre_current_utilization,.15,.98,.02,1.25), ...
        "post_step_charging",q_band(nominal.post_current_utilization,.15,.98,.02,1.25), ...
        "voltage",q_band(nominal.voltage_tail_V,2.7,4.25,1.5,5.0));
    A = bottleneck_mean(struct_values(Autilities),[.20 .30 .30 .20]);

    Qmetrics = struct( ...
        "battery_spread_K",nominal.battery_spread_K, ...
        "plate_spread_K",nominal.plate_spread_K, ...
        "battery_tail_drift_K_per_s",nominal.battery_tail_drift_K_per_s, ...
        "battery_distinct_tail_channels",nominal.battery_distinct_tail_channels, ...
        "plate_distinct_tail_channels",nominal.plate_distinct_tail_channels);
    Qutilities = struct( ...
        "battery_uniformity",q_low(nominal.battery_spread_K,2.5,12), ...
        "plate_uniformity",q_low(nominal.plate_spread_K,2.5,12), ...
        "tail_drift",q_low(abs(nominal.battery_tail_drift_K_per_s),.015,.12), ...
        "battery_spatial_field",q_high(nominal.battery_distinct_tail_channels,3,12), ...
        "plate_spatial_field",q_high(nominal.plate_distinct_tail_channels,3,12));
    Q = bottleneck_mean(struct_values(Qutilities),[.30 .25 .15 .15 .15]);

    lowIndex = find(names == "flow_pair_low",1);
    highIndex = find(names == "flow_pair_high",1);
    flowPair = paired_flow_metrics(rows(lowIndex),rows(highIndex));
    staticUtilities = [ ...
        static.distributed_battery, ...
        static.distributed_plate, ...
        static.thermal_liquid_path, ...
        static.physical_coolant_sensing, ...
        static.physical_charging_path, ...
        static.feedback_evidence, ...
        static.public_input_bindings];
    staticMechanism = bottleneck_mean(staticUtilities,ones(size(staticUtilities)));
    Mmetrics = struct( ...
        "static_mechanism_fraction",staticMechanism, ...
        "pressure_drop_ratio_high_over_low",flowPair.pressure_ratio, ...
        "battery_temperature_improvement_K",flowPair.battery_improvement_K, ...
        "plate_temperature_improvement_K",flowPair.plate_improvement_K, ...
        "low_flow_pressure_drop_bar",flowPair.low_pressure_drop_bar, ...
        "high_flow_pressure_drop_bar",flowPair.high_pressure_drop_bar);
    Mutilities = struct( ...
        "static_mechanism",staticMechanism, ...
        "flow_pressure_causality",q_high(flowPair.pressure_ratio,1.15,2.0), ...
        "flow_thermal_causality",sqrt( ...
            q_high(flowPair.battery_improvement_K,.02,.35)* ...
            q_high(flowPair.plate_improvement_K,.01,.25)));
    M = bottleneck_mean(struct_values(Mutilities),[.50 .25 .25]);

    operatingScores = zeros(numel(rows),1);
    dynamicScores = zeros(numel(rows),1);
    for index = 1:numel(rows)
        operatingParts = [ ...
            q_band(rows(index).battery_tail_max_K,278,326,270,345), ...
            q_low(rows(index).battery_spread_K,4,15), ...
            q_band(rows(index).coolant_pressure_drop_bar,.001,4.0,0,12), ...
            q_band(abs(rows(index).coolant_temperature_rise_K),.001,15,0,35), ...
            q_band(rows(index).post_current_utilization,.12,1.05,.02,1.30)];
        operatingScores(index) = bottleneck_mean(operatingParts, ...
            [.28 .22 .15 .10 .25]);
    end
    R = min(operatingScores);

    upIndex = find(names=="current_pair_up",1);
    controlIndex = find(names=="current_pair_control",1);
    downIndex = find(names=="current_pair_down",1);
    assert(~isempty(upIndex) && ~isempty(controlIndex) && ~isempty(downIndex), ...
        "F90_XTHERM05_CURRENT_TRIPLET_MISSING");
    up = rows(upIndex);
    control = rows(controlIndex);
    down = rows(downIndex);
    currentPair = paired_current_metrics( ...
        up,control,down);
    commonBound = min([ ...
        q_band(up.post_current_utilization,.80,1.05,.20,1.30), ...
        q_band(control.post_current_utilization,.80,1.05,.20,1.30), ...
        q_band(down.post_current_utilization,.80,1.05,.20,1.30)]);
    preMatch = q_low(currentPair.maximum_pre_pair_relative_difference,.015,.10);
    upScore = bottleneck_mean([ ...
        q_band(currentPair.up_effect_fraction,.85,1.15,.30,1.70), ...
        preMatch,commonBound],[.55 .20 .25]);
    downScore = bottleneck_mean([ ...
        q_band(currentPair.down_effect_fraction,.85,1.15,.30,1.70), ...
        preMatch,commonBound],[.55 .20 .25]);
    dynamicScores = [upScore;downScore];
    D = min(dynamicScores);

    coreGate = static.core_path_qualified;
    spatialGate = nominal.battery_distinct_tail_channels >= 2 && ...
        nominal.plate_distinct_tail_channels >= 2;
    flowGate = flowPair.pressure_ratio > 1.02 && ...
        (flowPair.battery_improvement_K > 0 || ...
        flowPair.plate_improvement_K > 0);
    currentGate = currentPair.up_effect_fraction > .30 && ...
        currentPair.up_effect_fraction < 1.70 && ...
        currentPair.down_effect_fraction > .30 && ...
        currentPair.down_effect_fraction < 1.70;
    gateReasons = strings(0,1);
    if ~coreGate
        gateReasons(end+1,1) = ...
            "core electro-thermal-fluid topology was not qualified"; %#ok<AGROW>
    end
    if ~spatialGate
        gateReasons(end+1,1) = ...
            "required temperature channels did not form independent spatial fields"; %#ok<AGROW>
    end
    if ~flowGate
        gateReasons(end+1,1) = ...
            "coolant-flow perturbation did not act causally on pressure and temperature"; %#ok<AGROW>
    end
    if ~currentGate
        gateReasons(end+1,1) = ...
            "CC-active limit triplet did not produce near-1:1 total-pack ampere response"; %#ok<AGROW>
    end
    G = coreGate && spatialGate && flowGate && currentGate;
    score = 0;
    if G
        score = 100*A^.20*Q^.17*M^.25*R^.23*D^.15;
    end

    receipt.G = G;
    receipt.gate_reasons = gateReasons;
    receipt.A = A;
    receipt.Q = Q;
    receipt.M = M;
    receipt.R = R;
    receipt.D = D;
    receipt.score = score;
    receipt.groups = struct("G",double(G),"A",A,"Q",Q,"M",M,"R",R,"D",D);
    receipt.raw_metrics = struct( ...
        "A",Ametrics,"Q",Qmetrics,"M",Mmetrics, ...
        "operating_scores",operatingScores, ...
        "dynamic_scores",dynamicScores, ...
        "paired_flow",flowPair, ...
        "paired_current",currentPair);
    receipt.utility_metrics = struct( ...
        "A",Autilities,"Q",Qutilities,"M",Mutilities, ...
        "R_worst",R,"D_worst",D);
    receipt.diagnostics_valid = true;
    receipt.failure_reasons = make_failure_reasons(G,A,Q,M,R,D,gateReasons);
catch scorerError
    receipt.error = string(getReport(scorerError,"extended","hyperlinks","off"));
    if strlength(receipt.error) > 0 && isempty(receipt.failure_reasons)
        receipt.failure_reasons = "scoring failed: " + string(scorerError.identifier);
    end
end
receipt.finished_at = timestamp();
write_json(fullfile(outDir,"receipt.json"),receipt);
end

function row = run_scenario(model,id,scenarioValues,def)
fields = fieldnames(scenarioValues);
for index = 1:numel(fields)
    assignin("base",fields{index},scenarioValues.(fields{index}));
end
set_param(model,"StopTime",num2str(def.sim.stop,"%.15g"), ...
    "ReturnWorkspaceOutputs","on");
out = sim(model);

series = cell(numel(def.outputs),1);
for index = 1:numel(def.outputs)
    name = def.outputs(index).name;
    series{index} = out.get(name);
    validate_timeseries(series{index},def.outputs(index).channels, ...
        def.sim.stop,name);
end
battery = matrix_data(series{1},24);
plate = matrix_data(series{2},24);
deltaT = matrix_data(series{3},1);
deltaP = matrix_data(series{4},1);
current = matrix_data(series{5},1);
voltage = matrix_data(series{6},1);

tb = double(series{1}.Time(:));
tp = double(series{2}.Time(:));
tdt = double(series{3}.Time(:));
tdp = double(series{4}.Time(:));
ti = double(series{5}.Time(:));
tv = double(series{6}.Time(:));
tailStart = def.sim.stop-40;
bTail = tb >= tailStart;
pTail = tp >= tailStart;
dtTail = tdt >= tailStart;
dpTail = tdp >= tailStart;
iTail = ti >= tailStart;
vTail = tv >= tailStart;
pre = ti >= max(10,scenarioValues.charge_step_time_s-35) & ...
    ti <= scenarioValues.charge_step_time_s-5;
post = ti >= min(def.sim.stop-35,scenarioValues.charge_step_time_s+35);
assert(nnz(bTail)>=5 && nnz(pTail)>=5 && nnz(dtTail)>=5 && ...
    nnz(dpTail)>=5 && nnz(pre)>=5 && nnz(post)>=5, ...
    "F90_XTHERM05_METRIC_WINDOWS");

batteryTailMeanByChannel = mean(battery(bTail,:),1);
plateTailMeanByChannel = mean(plate(pTail,:),1);
currentPre = mean(abs(current(pre)));
currentPost = mean(abs(current(post)));
targetPre = scenarioValues.charge_current_A;
targetPost = scenarioValues.charge_current_A* ...
    (1+scenarioValues.charge_step_fraction);
requestedDelta = targetPost-targetPre;
actualDelta = currentPost-currentPre;
if abs(requestedDelta) < 1e-9
    responseError = abs(actualDelta)/max(targetPre,1);
    directionScore = double(abs(actualDelta) <= .03*max(targetPre,1));
else
    responseError = abs(actualDelta-requestedDelta)/abs(requestedDelta);
    directionScore = double(sign(actualDelta)==sign(requestedDelta))* ...
        min(abs(actualDelta)/max(abs(requestedDelta),1e-9),1);
end
settling = settling_after_step(ti,abs(current), ...
    scenarioValues.charge_step_time_s,currentPost,.05*max(abs(currentPost),1));

row = empty_row;
row.id = id;
row.valid = true;
row.initial_temperature_error_K = ...
    max(abs(battery(1,:)-scenarioValues.initial_battery_temperature_K));
row.battery_tail_mean_K = mean(batteryTailMeanByChannel);
row.battery_tail_max_K = max(batteryTailMeanByChannel);
row.battery_tail_min_K = min(batteryTailMeanByChannel);
row.battery_spread_K = max(batteryTailMeanByChannel)- ...
    min(batteryTailMeanByChannel);
row.plate_tail_mean_K = mean(plateTailMeanByChannel);
row.plate_tail_max_K = max(plateTailMeanByChannel);
row.plate_tail_min_K = min(plateTailMeanByChannel);
row.plate_spread_K = max(plateTailMeanByChannel)- ...
    min(plateTailMeanByChannel);
row.battery_tail_drift_K_per_s = linear_slope(tb(bTail), ...
    mean(battery(bTail,:),2));
row.battery_distinct_tail_channels = ...
    distinct_count(batteryTailMeanByChannel,1e-5);
row.plate_distinct_tail_channels = ...
    distinct_count(plateTailMeanByChannel,1e-5);
row.coolant_temperature_rise_K = mean(deltaT(dtTail));
row.coolant_pressure_drop_bar = mean(abs(deltaP(dpTail)));
row.current_pre_A = currentPre;
row.current_post_A = currentPost;
row.current_limit_before_A = targetPre;
row.current_limit_after_A = targetPost;
row.pre_current_utilization = currentPre/max(abs(targetPre),1);
row.post_current_utilization = currentPost/max(abs(targetPost),1);
row.pre_current_error = abs(currentPre-targetPre)/max(abs(targetPre),1);
row.post_current_error = abs(currentPost-targetPost)/max(abs(targetPost),1);
row.current_step_response_error = responseError;
row.current_step_direction_score = directionScore;
row.current_step_settling_s = settling;
row.voltage_tail_V = mean(voltage(vTail));
row.electrical_power_tail_W = mean(abs(current(iTail)))* ...
    mean(abs(voltage(vTail)))*96;
row.error = "";
end

function audit = static_audit(model,def)
blocks = find_system(model,"LookUnderMasks","all","FollowLinks","on", ...
    "Type","Block");
counts = struct( ...
    "battery_components",0, ...
    "thermal_storage_or_conduction",0, ...
    "thermal_liquid_flow_components",0, ...
    "thermal_liquid_pipes_or_restrictions",0, ...
    "pressure_temperature_sensors",0, ...
    "controlled_current_sources",0, ...
    "electrical_voltage_measurements",0, ...
    "controller_like",0);
for index = 1:numel(blocks)
    text = lower(identity_text(blocks{index}));
    counts.battery_components = counts.battery_components + ...
        double(contains(text,"battery") && ...
        ~contains(text,"to workspace"));
    counts.thermal_storage_or_conduction = ...
        counts.thermal_storage_or_conduction + ...
        double(contains(text,"thermal mass") || ...
        contains(text,"thermal conductor") || ...
        contains(text,"cooling plate"));
    counts.thermal_liquid_flow_components = ...
        counts.thermal_liquid_flow_components + ...
        double(contains(text,"thermal_liquid") || contains(text,"(tl)"));
    counts.thermal_liquid_pipes_or_restrictions = ...
        counts.thermal_liquid_pipes_or_restrictions + ...
        double(contains(text,"pipe (tl)") || ...
        contains(text,"local restriction (tl)") || ...
        contains(text,"thermal_liquid.elements.pipe"));
    counts.pressure_temperature_sensors = ...
        counts.pressure_temperature_sensors + ...
        double((contains(text,"pressure") && contains(text,"temperature") && ...
        contains(text,"sensor")) || ...
        contains(text,"pressure_temperature_sensor"));
    counts.controlled_current_sources = counts.controlled_current_sources + ...
        double(contains(text,"controlled current source") || ...
        contains(text,"controlled_current"));
    counts.electrical_voltage_measurements = ...
        counts.electrical_voltage_measurements + ...
        double(contains(text,"voltage sensor") || ...
        contains(text,"battery voltage"));
    counts.controller_like = counts.controller_like + ...
        double(contains(text,"controller") || contains(text,"control logic"));
end

logs = strings(numel(def.outputs),1);
logsValid = false(numel(def.outputs),1);
for index = 1:numel(def.outputs)
    found = find_system(model,"LookUnderMasks","all","FollowLinks","on", ...
        "BlockType","ToWorkspace","VariableName",def.outputs(index).name);
    if numel(found)==1
        logs(index) = string(found{1});
        logsValid(index) = strcmpi(get_param(found{1},"SaveFormat"),"Timeseries") && ...
            strcmpi(get_param(found{1},"MaxDataPoints"),"inf");
    end
end

usedVariables = strings(0,1);
try
    variables = Simulink.findVars(model);
    usedVariables = string({variables.Name}).';
catch
end
bindingFraction = mean(ismember(string({def.public_inputs.name}),usedVariables));
distributedBattery = q_high(counts.battery_components,4,20);
% A custom finite-capacity plate can contain all 24 partitions inside one
% composite component; spatial independence is separately verified from
% the 24 measured trajectories, so counting 12 visible plate blocks would
% incorrectly reject the exact physical source.
distributedPlate = q_high(counts.thermal_storage_or_conduction,0,2);
thermalLiquidPath = sqrt( ...
    q_high(counts.thermal_liquid_flow_components,4,15)* ...
    q_high(counts.thermal_liquid_pipes_or_restrictions,3,20));
physicalSensing = q_high(counts.pressure_temperature_sensors,0,1);
currentOrigin = upstream_contains(logs(5),["battery"],6);
voltageOrigin = upstream_contains(logs(6),["battery"],6);
outputOrigins = [ ...
    upstream_contains(logs(1),["battery"],6), ...
    upstream_contains(logs(2),["battery","cooling plate"],6), ...
    upstream_contains(logs(3),["ps-simulink"],3), ...
    upstream_contains(logs(4),["ps-simulink"],3), ...
    currentOrigin,voltageOrigin];
voltageSource = immediate_upstream(logs(6));
feedbackConnection = downstream_contains(voltageSource, ...
    ["controller","control logic","cc-cv"],6);
physicalCharging = sqrt( ...
    q_high(counts.controlled_current_sources,0,1)* ...
    q_high(counts.battery_components,1,5)*currentOrigin);
feedbackEvidence = sqrt( ...
    voltageOrigin* ...
    feedbackConnection* ...
    q_high(counts.controller_like,0,1)* ...
    q_high(counts.controlled_current_sources,0,1));
audit = struct( ...
    "counts",counts, ...
    "output_log_paths",logs, ...
    "output_logs_valid",logsValid, ...
    "pack_current_physical_origin",currentOrigin, ...
    "cell_voltage_physical_origin",voltageOrigin, ...
    "output_physical_origins",outputOrigins, ...
    "voltage_feedback_connection",feedbackConnection, ...
    "used_public_inputs",usedVariables(ismember(usedVariables, ...
        string({def.public_inputs.name}))), ...
    "distributed_battery",distributedBattery, ...
    "distributed_plate",distributedPlate, ...
    "thermal_liquid_path",thermalLiquidPath, ...
    "physical_coolant_sensing",physicalSensing, ...
    "physical_charging_path",physicalCharging, ...
    "feedback_evidence",feedbackEvidence, ...
    "public_input_bindings",bindingFraction, ...
    "core_path_qualified", ...
        all(logsValid) && distributedBattery>=.5 && ...
        distributedPlate>=.5 && thermalLiquidPath>=.5 && ...
        physicalSensing>=.5 && physicalCharging>=.5 && ...
        feedbackEvidence>=.5 && all(outputOrigins>=.5) && ...
        bindingFraction>=.85);
end

function score = upstream_contains(logPath,patterns,maxDepth)
score = 0;
if strlength(logPath)==0
    return;
end
try
    handle = getSimulinkBlockHandle(logPath);
catch
    return;
end
if handle<=0,return;end
queue = string(logPath);
seen = strings(0,1);
for depth = 1:maxDepth
    next = strings(0,1);
    for index = 1:numel(queue)
        block = queue(index);
        if any(seen==block),continue;end
        seen(end+1,1) = block; %#ok<AGROW>
        text = lower(identity_text(block));
        if any(contains(text,lower(patterns)))
            score = 1;
            return;
        end
        try
            ports = get_param(block,"PortHandles");
            if ~isfield(ports,"Inport"),continue;end
            for port = ports.Inport(:).'
                line = get_param(port,"Line");
                if line<=0,continue;end
                source = get_param(line,"SrcBlockHandle");
                if source>0
                    next(end+1,1) = string(getfullname(source)); %#ok<AGROW>
                end
            end
        catch
        end
    end
    queue = unique(next);
end
end

function source = immediate_upstream(block)
source = "";
if strlength(block)==0,return;end
try
    ports = get_param(block,"PortHandles");
    if ~isfield(ports,"Inport") || isempty(ports.Inport),return;end
    line = get_param(ports.Inport(1),"Line");
    if line<=0,return;end
    handle = get_param(line,"SrcBlockHandle");
    if handle>0,source = string(getfullname(handle));end
catch
end
end

function score = downstream_contains(source,patterns,maxDepth)
score = 0;
if strlength(source)==0,return;end
queue = string(source);
seen = strings(0,1);
for depth = 1:maxDepth
    next = strings(0,1);
    for index = 1:numel(queue)
        block = queue(index);
        if any(seen==block),continue;end
        seen(end+1,1) = block; %#ok<AGROW>
        if depth>1
            text = lower(identity_text(block));
            if any(contains(text,lower(patterns)))
                score = 1;
                return;
            end
        end
        try
            ports = get_param(block,"PortHandles");
            if ~isfield(ports,"Outport"),continue;end
            for port = ports.Outport(:).'
                line = get_param(port,"Line");
                if line<=0,continue;end
                destinations = get_param(line,"DstBlockHandle");
                destinations = destinations(destinations>0);
                for handle = destinations(:).'
                    next(end+1,1) = string(getfullname(handle)); %#ok<AGROW>
                end
            end
        catch
        end
    end
    queue = unique(next);
end
end

function text = identity_text(block)
