function q = bottleneck_mean(values,weights)
values = min(max(double(values(:)),0),1);
weights = double(weights(:));
weights = weights/sum(weights);
q = sqrt(sum(weights.*values)*min(values));
end

function values = struct_values(source)
names = fieldnames(source);
values = zeros(numel(names),1);
for index = 1:numel(names)
    values(index) = source.(names{index});
end
end

function q = q_low(value,good,bad)
if ~isfinite(value),q=0;return;end
q = clip((bad-value)/(bad-good));
end

function q = q_high(value,bad,good)
if ~isfinite(value),q=0;return;end
q = clip((value-bad)/(good-bad));
end

function q = q_band(value,lowGood,highGood,lowBad,highBad)
if ~isfinite(value),q=0;return;end
if value>=lowGood && value<=highGood
    q=1;
elseif value<lowGood
    q=q_high(value,lowBad,lowGood);
else
    q=q_low(value,highGood,highBad);
end
end

function q = clip(value)
q = min(max(value,0),1);
end

function reasons = make_failure_reasons(G,A,Q,M,R,D,gateReasons)
reasons = gateReasons;
labels = ["A nominal accuracy","Q temperature-field quality", ...
    "M physical mechanism/causality","R worst operating point", ...
    "D current-limit-change response"];
values = [A Q M R D];
for index = 1:numel(values)
    if values(index)<.60
        reasons(end+1,1) = labels(index) + ...
            " group below 0.60: " + compose("%.4f",values(index)); %#ok<AGROW>
    end
end
if G && isempty(reasons)
    reasons = strings(0,1);
end
end

